private static function format(string $int, string $frac, int $decimals, bool $negative): string
{
    $w = self::unpad($int) === '' ? '0' : self::unpad($int);
    if (0 >= $decimals) {
        return $w;
    }

    $s = $w . '.' . $frac;
    if (str_starts_with($s, '.')) {
        $s = '0' . $s;
    }
    if ('.' === $s[strlen($s) - 1] && $decimals > 0) {
        $s = $w . '.' . str_repeat('0', $decimals);
    }

    return $negative ? '-' . $s : $s;
}

